MBO_st.name='MBO'; 
MBO_st.lat=43.9775;
MBO_st.lon=-121.6861;
MBO_st.alt=2800;
MBO_st.env='Mt';
MBO_st.footp='Mx';
%%

MBO_rd=read_betsy_2026('C:\github_trend\raw_data\MBO_dataonly_wRH_gml.csv', MBO_st.name); %[output:7bce0832]

names_rd=fieldnames(MBO_rd);
%%
% missing data are not removed: data >5e4 should be removed, U data ==999
for i=1: length(names_rd)-3 %[output:group:2b969130]
    MBO_rd.(names_rd{i})(MBO_rd.(names_rd{i})<=-99 || MBO_rd.(names_rd{i})>=999 )=NaN ; %[output:8df0d410]
end %[output:group:2b969130]
%%
datevec(MBO_rd.Time(1)) % begin in 2008, but complete year since 2012 %[output:5007b6e3]
datevec(MBO_rd.Time(end)) % end in 2024 %[output:83582536]
prctile(MBO_rd.U1_S11,[5 50 95]) % < 30%, ok.  %[output:5ecffb96]
prctile(MBO_rd.U0_S11,[5 50 95]) %[output:410e078c]
plotFigControl(MBO_rd,MBO_st.name); %--> absorption cannot be used %[output:58b806e5] %[output:5d195249] %[output:5ffa6e2e] %[output:11c1401b] %[output:0f2dab2d] %[output:018c2c4c] %[output:9152abf4]
%%
% try to homogeneised scat and backscat between PM1 and PM10
P_both=timerange('2018-04-14','2020-10-29');
ratio_STN=nanstd(MBO_rd.BsG0_TSI(P_both)./MBO_rd.BsG1_TSI(P_both)) % 0.2899 %[output:4dbab2e4]
ratio_mean=nanmean(MBO_rd.BsG0_TSI(P_both))/nanmean(MBO_rd.BsG1_TSI(P_both)) % 1.0318 %[output:2a79e250]
ratio_median=nanmedian(MBO_rd.BsG0_TSI(P_both))/nanmedian(MBO_rd.BsG1_TSI(P_both)) % 1.0120 %[output:44406dd5]
figure; %[output:571a6423]
plot(MBO_rd.BsG0_TSI(P_both),MBO_rd.BsG1_TSI(P_both),'.'); %basic fit: y=0.9042x-0.8086, inverse slope=1.11 %[output:571a6423]
ylabel('BsG PM1'); %[output:571a6423]
xlabel('BsG PM10'); %[output:571a6423]
grid on; %[output:571a6423]
legend('period 2018-04-14 2020-10-29','fit') %[output:9b14d5f7] %[output:571a6423]
% fit between both data: slope 0.9955x+0.1021
fit_test=robustfit(MBO_rd.BsG0_TSI(P_both),MBO_rd.BsG1_TSI(P_both)) % 0.0385, slope=0.9016 , inverse 1.1091 %[output:3827128f]
% 1/slope fit and robust fit =1.1: use it as constant
 cte_PM1_PM10=1.1;
%%
   % time serie PM1+PM10
P1=timerange('2012-10-11','2018-08-01');
P2=timerange('2018-08-01','2025-01-01');

% 
MBO_rd.BsG_homo=NaN(size(MBO_rd.BsG0_TSI));
MBO_rd.BsG_homo(P1)=MBO_rd.BsG1_TSI(P1).*cte_PM1_PM10; 
MBO_rd.BsG_homo(P2)=MBO_rd.BsG0_TSI(P2);

MBO_rd.BsB_homo=NaN(size(MBO_rd.BsB0_TSI));
MBO_rd.BsB_homo(P1)=MBO_rd.BsB1_TSI(P1).*cte_PM1_PM10; 
MBO_rd.BsB_homo(P2)=MBO_rd.BsB0_TSI(P2);

MBO_rd.BsR_homo=NaN(size(MBO_rd.BsR0_TSI));
MBO_rd.BsR_homo(P1)=MBO_rd.BsR1_TSI(P1).*cte_PM1_PM10; 
MBO_rd.BsR_homo(P2)=MBO_rd.BsR0_TSI(P2);

%%
% try to homogeneised scat and backscat between PM1 and PM10
P_both=timerange('2018-04-14','2020-10-29');
ratio_STN=nanstd(MBO_rd.BbsG0_TSI(P_both)./MBO_rd.BbsG1_TSI(P_both)) % 0.1572 %[output:8b2cfcd2]
ratio_mean=nanmean(MBO_rd.BbsG0_TSI(P_both))/nanmean(MBO_rd.BbsG1_TSI(P_both)) % 1.1133 %[output:0c100c20]
ratio_median=nanmedian(MBO_rd.BbsG0_TSI(P_both))/nanmedian(MBO_rd.BbsG1_TSI(P_both)) % 1.0399 %[output:31a15ea0]
figure; %[output:75a2da72]
plot(MBO_rd.BbsG0_TSI(P_both),MBO_rd.BbsG1_TSI(P_both),'.'); %basic fit: y=0.9042x-0.8086, inverse slope=1.11 %[output:75a2da72]
ylabel('BbsG PM1'); %[output:75a2da72]
xlabel('BbsG PM10'); %[output:75a2da72]
grid on; %[output:75a2da72]
legend('period 2018-04-14 2020-10-29','fit') %[output:20abd848] %[output:75a2da72]
% fit between both data: slope 0.8436*x + 0.1363
fit_test=robustfit(MBO_rd.BbsG0_TSI(P_both),MBO_rd.BbsG1_TSI(P_both)) % 0.0621, slope=0.8466 , inverse 1.18 %[output:0282746e]
% 1/slope fit and robust fit =1.1: use it as constant
 cte_Bbs_PM1_PM10=1.2;
%%
   % time serie PM1+PM10
P1=timerange('2012-10-11','2018-08-01');
P2=timerange('2018-08-01','2025-01-01');

% 
MBO_rd.BbsG_homo=NaN(size(MBO_rd.BbsG0_TSI));
MBO_rd.BbsG_homo(P1)=MBO_rd.BbsG1_TSI(P1).*cte_Bbs_PM1_PM10; 
MBO_rd.BbsG_homo(P2)=MBO_rd.BbsG0_TSI(P2);

MBO_rd.BbsB_homo=NaN(size(MBO_rd.BbsB0_TSI));
MBO_rd.BbsB_homo(P1)=MBO_rd.BbsB1_TSI(P1).*cte_Bbs_PM1_PM10; 
MBO_rd.BbsB_homo(P2)=MBO_rd.BbsB0_TSI(P2);

MBO_rd.BbsR_homo=NaN(size(MBO_rd.BbsR0_TSI));
MBO_rd.BbsR_homo(P1)=MBO_rd.BbsR1_TSI(P1).*cte_Bbs_PM1_PM10; 
MBO_rd.BbsR_homo(P2)=MBO_rd.BbsR0_TSI(P2);
%%
% BP detection for scat coef and backscat

names_sc={'BsB_homo', 'BsG_homo', 'BsR_homo'};
break_MBO_scat_BP=change_point_analysis_Def(MBO_rd,names_sc,0.05,'MBO','scattering'); %[output:03ecc5fe] %[output:95bbbb58] %[output:9e48b6fe] %[output:5e14ce35]
T_MBO_scat_BP=make_table_breakpoints_def(break_MBO_scat_BP);

names_bsc={'BbsB_homo', 'BbsG_homo', 'BbsR_homo'};
break_MBO_bscat_BP=change_point_analysis_Def(MBO_rd,names_bsc,0.05,'MBO','Backscattering'); %[output:302ed7c1]
T_MBO_bscat_BP=make_table_breakpoints_def(break_MBO_bscat_BP);
%%
% compute expS
lambdaSC=[450;550;700] %[output:4a130be8]
% compute exp and SSA separately, MBO has too many instruments
%compute exp scat and BF

MBO_cal=compute_exp_D(MBO_rd,names_sc,lambdaSC);
plotFigControl_cal(MBO_cal,MBO_st.name); %[output:0f6ce38d] %[output:7484e74e] %[output:25a9f1f6]
%%
names_exp={'expS_bg'};
break_MBO_exp_BP=change_point_analysis_Def(MBO_cal,names_exp,0.05,'MBO','scattering exp'); %[output:9a4192a9] %[output:3ce38e88]
T_MBO_exp_BP=make_table_breakpoints_def(break_MBO_exp_BP); %[output:3eb331bd] %[output:9fc6bb47]
%%
% trend
MBO_tr=synchronize(MBO_rd,MBO_cal);

MBO_tr.y=year(MBO_tr.Time);
% begin at the beginning of a year: 2007 for abs, 2009 for scat
%end: 2025
P=timerange('2012-01-01','2025-01-01');
MBO_tr=MBO_tr(P,:);

names=fieldnames(MBO_tr);

c=startsWith(names,["Ta";"Pa";"Bbs";"Ba";"U"]) | endsWith(names,["RRneph";"TSI";"Bbs";"Ba"]);
N=names(c); %[output:058d24cd]
for i=1:length(N)
   MBO_tr.(N{i})=[];
end
 MBO_tr.BsB_homo=[];
MBO_tr.BsR_homo=[];


MBO_tr.expS_br=[];
MBO_tr.expS_gr=[];
%%
[MBO_result_MK,MBO_result_LMSlog,MBO_result_LMSlin]=all_trend_STN(MBO_tr,MBO_st); %[output:77e52f35] %[output:8d08fe85] %[output:9dc43851] %[output:703ef29f] %[output:40a491e2] %[output:69e2970d] %[output:22eb381b] %[output:71d9cfe0] %[output:3979c28f] %[output:4ef3ee59] %[output:08be9c24] %[output:7313f007] %[output:1c1e6518] %[output:24f9de77] %[output:8ee7be08] %[output:8d689faf] %[output:6d22885d] %[output:37e06b6b] %[output:8690d405] %[output:7c1be7bc] %[output:13baac46] %[output:9c193ea1] %[output:577bc9b7] %[output:909aec64] %[output:1d5a7373] %[output:97e2be76] %[output:8873fe81] %[output:3c32903d] %[output:5ca1e3d6] %[output:7e0e91d2] %[output:63a4875c] %[output:8f9b013f] %[output:0b21504c] %[output:45fd42f4] %[output:0e1c3571] %[output:01a62dd1] %[output:0a13adf4] %[output:7f1b3db9] %[output:7caa2daa] %[output:1e199910] %[output:80bd22b4] %[output:7728a171] %[output:0412a3a6] %[output:04bdd3fe] %[output:605c7930] %[output:37acf70d] %[output:37d5f91b] %[output:9e77571a] %[output:846d1c58] %[output:70a995a6] %[output:9fdf463d] %[output:6d4b889b] %[output:75d23ade] %[output:0b6bb3a0] %[output:0328ecd9] %[output:5c714c91] %[output:31afe55b] %[output:4f3d09a5] %[output:434dc821] %[output:7105c4b9] %[output:1cc95032] %[output:18697255] %[output:0fce9194] %[output:6844dc47] %[output:9c557863]

writetable(MBO_result_MK,'MBO_res_MK.txt'); %, 'delimiter',',' )
writetable(MBO_result_LMSlog,'MBO_res_LMSlog.txt'); 
writetable(MBO_result_LMSlin,'MBO_res_LMSlin.txt'); 
plot_10y_in_two(MBO_result_MK, MBO_st,'y'); %[output:606441e7] %[output:5e34de33]

